package io.agentplm.api.security;

import java.util.Map;

import io.quarkus.test.junit.QuarkusTestProfile;

public class AuthEnforcementTestProfile implements QuarkusTestProfile {

    @Override
    public Map<String, String> getConfigOverrides() {
        return Map.of(
                "quarkus.oidc.enabled", "false",
                "quarkus.http.auth.proactive", "true",
                "quarkus.http.auth.permission.public.paths", "/api/health,/api/info",
                "quarkus.http.auth.permission.public.policy", "permit",
                "quarkus.http.auth.permission.authenticated.paths", "/api/seasons,/api/seasons/*",
                "quarkus.http.auth.permission.authenticated.policy", "authenticated");
    }
}

package io.agentplm.api.security;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

import io.quarkus.test.junit.QuarkusTest;
import io.quarkus.test.junit.TestProfile;
import org.junit.jupiter.api.Test;

@QuarkusTest
@TestProfile(AuthEnforcementTestProfile.class)
class SeasonResourceAuthIT {

    @Test
    void healthRemainsPublic() {
        given()
                .when()
                .get("/api/health")
                .then()
                .statusCode(200)
                .body("status", equalTo("UP"));
    }

    @Test
    void seasonsRequiresAuthentication() {
        given()
                .when()
                .get("/api/seasons")
                .then()
                .statusCode(401)
                .body("error", equalTo("Authentication required"));
    }
}

package io.agentplm.api;

import static org.junit.jupiter.api.Assertions.assertEquals;

import io.quarkus.security.UnauthorizedException;
import jakarta.ws.rs.core.Response;
import org.junit.jupiter.api.Test;

class UnauthorizedExceptionMapperTest {

    @Test
    void mapsBlankMessageToDefault() {
        UnauthorizedExceptionMapper mapper = new UnauthorizedExceptionMapper();
        Response response = mapper.toResponse(new UnauthorizedException());
        assertEquals(401, response.getStatus());
        assertEquals("Authentication required", ((java.util.Map<?, ?>) response.getEntity()).get("error"));
    }
}

